class LessonProgress {
  getPercentage(): number {
    if (this.totalLessons === 0) return 0;
    return (this.completedCount / this.totalLessons) * 100;
  }
}

class LessonCompletionService {
  async completeLessonForUser(userId: string, lessonId: string) {
    if (!userId || !lessonId) throw new ValidationError(...);
    const progress = await this.progressRepository.getProgress(...);
    progress.addCompletedLesson(lessonId);
    await this.progressRepository.save(progress);
    this.eventBus.emit("LessonCompleted", ...);
  }
}

