class AiTutorService {
  async explainError(context) {
    if (!await quotaManager.canRequest()) return fallback();
    const cached = await cache.get(context.id);
    if (cached) return cached;
    try {
      const explanation = await aiProvider.explain(context);
      await cache.set(context.id, explanation);
      this.eventBus.emit("ExplanationGenerated", ...);
      return explanation;
    } catch (error) {
      this.logger.error(...);
      return { fallback: true, message: "Serviço indisponível" };
    }
  }
}

