function unlockNextLesson(userId, completedLessonId) {
  const lesson = db.query(
    `SELECT * FROM lessons WHERE id = '${completedLessonId}'`
  )[0];
  const nextLesson = db.query(
    `SELECT * FROM lessons WHERE module_id = '${lesson.module_id}' AND order > ${lesson.order} LIMIT 1`
  )[0];
  if (nextLesson) {
    db.query(
      `UPDATE lessons_unlocked SET unlocked = 1 WHERE user_id = '${userId}' AND lesson_id = '${nextLesson.id}'`
    );
    sendSlackNotification(`User ${userId} unlocked ${nextLesson.id}`);
    return { success: true, unlockedLessonId: nextLesson.id };
  }
  return { success: false, message: "No more lessons" };
}
